INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62298058', 62298058, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Konsumsi Rapat (Makan + Kudapan) Untuk Kegiatan Pengambilan Sumpah Jabatan Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Republik Indonesia Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 14580000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Pekerjaan ini mencakup penyediaan konsumsi kegiatan berupa makan dan kudapan untuk mendukung pelaksanaan kegiatan pengambilan sumpah jabatan. Konsumsi disediakan sebanyak 180 OK yang diperuntukkan bagi 60 orang untuk 3 kegiatan. Kegiatan meliputi penyediaan, pengemasan, dan penyerahan makan dan kudapan sesuai jadwal pelaksanaan kegiatan. Pelaksanaan pekerjaan dilakukan dengan memperhatikan ketepatan waktu, kebersihan, keamanan pangan, serta efisiensi penggunaan anggaran.', 'Konsumsi makan yang disediakan berupa makanan utama siap santap yang terdiri atas nasi, lauk pauk, sayuran, dan buah sebagai pelengkap. Makanan diproduksi secara higienis dengan bahan baku segar dan halal serta memiliki porsi yang cukup dan seimbang. Kudapan yang disediakan berupa makanan ringan seperti roti, kue, atau snack sejenis yang sesuai untuk kegiatan pengambilan sumpah jabatan yang disajikan dalam kondisi segar, tidak kedaluwarsa, dan memiliki cita rasa yang baik. Jenis dan jumlah makan dan kudapan disesuaikan dengan kebutuhan sebanyak 180 OK untuk 60 orang selama 3 (tiga) kegiatan. Seluruh makanan dan kudapan dikemas secara rapi, aman, dan diserahkan dalam kondisi baik sesuai ketentuan administrasi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 392928);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62989309', 62989309, 'analyze_legacy', 'Kab. Magetan', 'kabkota', 'KELURAHAN KEBONAGUNG', 'Belanja Tagihan Air', 'Jasa Lainnya', 'Dikecualikan', 'Jawa Timur, Magetan (Kab.)', 1125000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Tarif Air Minum PDAM;', 'Kelompok II (Non Niaga), Instansi Pemerintah, Blok II : >10-20 M3;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 392929);
