INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62344485', 62344485, 'analyze_legacy', 'Badan Nasional Pencarian dan Pertolongan', 'central', 'Badan Nasional Pencarian dan Pertolongan', 'Optimalisasi Email Basarnas', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 440105000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Paket, @ 440105000)', '1. Melakukan assessment sistem email existing Basarnas. 2. Melakukan perpanjangan lisensi pengguna dan antispamnya. 3. Melakukan pembaruan versi Zimbra yang digunakan agar terhindar dari bug dan celah keamanan. 4. Mengembangkan webmail dengan membuat modul lupa kata sandi agar memudahkan pengguna untuk melakukan reset password akses ke webmail. 5. Memastikan sistem keamanan baik dari segi akses system administrator maupun pengguna secara keseluruhan. 6. Memastikan LDAP (Light Directory Access Protocol) based login integrasi ke aplikasi Basarnas. 7. Mengimplementasikan konsep-konsep keamanan dan availabilitas sistem, termasuk dan tidak terbatas kepada transaksi data yang aman dan handal, implementasi sistem cadangan, automated data backup system dan recovery system. 8. Melakukan Preventive Maintenance dan Corrective Maintenance pada System Zimbra untuk memastikan sistem bekerja sebagai mestinya selama 1 Tahun. 9. Bekerja sama dengan tim pengembang lain untuk saling mengintegrasikan Sistem lnformasi/ Aplikasi Basarnas. Ruang lingkup lainnya: 1. Masa garansi pemeliharaan selama 12 (dua belas) bulan. 2. Melakukan transfer knowledge kepada pengguna email. 3. Penyedia wajib membuat buku petunjuk pemakaian untuk membantu dalam penggunaan aplikasi. 4. Penyedia wajib membuat buku petunjuk penggunaan aplikasi dalam bentuk cetakan (buku) dan DVD/ flashdisk. 5. Penyedia wajib menyerahkan source program dalam bentuk DVD/ flashdisk.', 'Spesifikasi Perangkat Keras - HPE Proliant DL380 Gen 9 - Processor 40 CPU - RAM 32GB - Storage 1TB Spesifikasi Perangkat Lunak - Operating System Ubuntu Server - Email Application Zimbra NE', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 393560);
