INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62298787', 62298787, 'analyze_legacy', 'Kab. Madiun', 'kabkota', 'Dinas Komunikasi dan Informatika', 'Penyediaan Layanan Akses Internet', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Madiun (Kab.)', 1593906021, 'December 2025', 'APBD', 1, 1, '1 Tahun', 'Penyediaan layanan akses internet dengan kapasitas bandwidth tertentu untuk mendukung operasional pemerintahan daerah, termasuk instalasi, konfigurasi, pemeliharaan, penanganan gangguan, dan pemenuhan SLA selama masa kontrak.', 'Spesifikasi Pekerjaan meliputi penyediaan layanan akses internet berbasis jasa untuk memenuhi kebutuhan Pemerintah Daerah dengan konektivitas ke jaringan internet publik, dengan kapasitas bandwidth sesuai kebutuhan OPD yang dinyatakan dalam satuan Mbps, bersifat dedicated atau shared sesuai perencanaan, dan tersedia selama 24 (dua puluh empat) jam sehari dan 7 (tujuh) hari seminggu. Media koneksi menggunakan fiber optic, wireless, atau media lain yang layak secara teknis, yang ditentukan berdasarkan kondisi lokasi dan hasil survei teknis penyedia. Pekerjaan mencakup instalasi jalur koneksi sampai dengan titik serah layanan, konfigurasi perangkat jaringan agar layanan berfungsi secara optimal, serta pengujian koneksi sebelum dilakukan serah terima layanan. Penyedia wajib menyediakan dan mengonfigurasi perangkat pendukung yang diperlukan untuk kelancaran layanan, seperti modem, yang menjadi tanggung jawab penyedia selama masa kontrak. Kualitas layanan harus memenuhi tingkat ketersediaan minimal. Selama masa layanan, penyedia wajib melakukan pemantauan jaringan secara berkala, menyediakan layanan helpdesk dan dukungan teknis, serta melakukan perbaikan gangguan tanpa biaya tambahan. Penyedia juga wajib menjamin keamanan jaringan melalui perlindungan dasar terhadap gangguan serta tidak melakukan pembatasan akses yang merugikan pengguna tanpa persetujuan. Selain itu, penyedia wajib menyampaikan laporan pemakaian dan kinerja layanan secara berkala setiap bulan serta laporan insiden gangguan beserta penyelesaiannya, dengan masa layanan selama 12 (dua belas) bulan atau sesuai dengan ketentuan dalam kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 393617);
