INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62300216', 62300216, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Barang Persediaan Pemeliharaan Gedung dan Bangunan Untuk Kegiatan Operasional dan Pemeliharaan Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyaratan Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 90000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 Tahun', 'Paket ini merupakan kegiatan pengadaan barang persediaan pemeliharaan gedung dan bangunan pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyaratan untuk jangka waktu 1 tahun anggaran. Pengadaan dilakukan untuk memenuhi kebutuhan bahan dan perlengkapan pemeliharaan rutin gedung dan bangunan agar kondisi sarana dan prasarana kantor tetap terjaga yang berfungsi dengan baik, serta mendukung kelancaran pelaksanaan tugas dan fungsi kantor.', 'Barang persediaan yang diadakan meliputi tidak terbatas pada bahan dan perlengkapan pemeliharaan gedung dan bangunan, seperti cat dan bahan pelapis, perlengkapan listrik, perlengkapan sanitasi, bahan bangunan ringan, serta alat dan perlengkapan pendukung pemeliharaan lainnya. Barang yang disediakan harus dalam kondisi baru, layak pakai, dan berkualitas baik sesuai standar yang berlaku, serta diserahkan secara bertahap atau sesuai kebutuhan selama 1 tahun anggaran dengan memperhatikan ketentuan administrasi dan pengelolaan persediaan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 395833);
