INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62301035', 62301035, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa Komunikasi Accelerograph dan Intensitymeter', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 700000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Sewa Komunikasi Fiber Optik BMKG merupakan penyediaan saluran komunikasi berbasis fiber optik untuk mendukung operasional perangkat accelerograph dan intensity meter dalam rangka kelancaran pengumpulan, pengiriman, dan penyebaran data serta informasi. Layanan ini memastikan data dari sensor accelerograph dan intensity meter dapat ditransmisikan secara berkesinambungan menuju BMKG pusat. Sistem komunikasi dirancang dengan menjadikan fiber optik sebagai tulang punggung jaringan guna menjamin keandalan, stabilitas, dan kontinuitas pengiriman data secara real-time. Pemilihan fiber optik didasarkan pada karakteristiknya yang memiliki kapasitas bandwidth tinggi, latency rendah, serta ketahanan terhadap gangguan elektromagnetik, sehingga mampu memenuhi kebutuhan monitoring gempa dengan tingkat akurasi dan kecepatan yang optimal.', 'Untuk mendukung kegiatan operasional kelangsungan pengiriman dan pertukaran data dan informasi secara tepat dan akurat dan tersedianya layanan jaringan komunikasi FO yang handal dengan SLA minimal 99% /Bulan di 114 lokasi site accelerograph dan intensity meter.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 397304);
